301	
302	    protected void setPetsInternal(Set<Pet> pets) {
303	        this.pets = pets;
304	    }
305	
306	    public List<Pet> getPets() {
307	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
308	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
309	        return Collections.unmodifiableList(sortedPets);
310	    }
311	
312	    public void setPets(List<Pet> pets) {
313	        this.pets = new HashSet<>(pets);
314	    }
315	
316	    public void addPet(Pet pet) {
