318	        pet.setOwner(this);
319	    }
320	
321	    /**
322	     * Return the Pet with the given name, or null if none found for this Owner.
323	     *
324	     * @param name to test
325	     * @return true if pet name is already in use
326	     */
327	    public Pet getPet(String name) {
328	        return getPet(name, false);
329	    }
330	
331	    /**
332	     * Return the Pet with the given name, or null if none found for this Owner.
333	     *
334	     * @param name to test
335	     * @return true if pet name is already in use
336	     */
337	    public Pet getPet(String name, boolean ignoreNew) {
338	        name = name.toLowerCase();
339	        for (Pet pet : getPetsInternal()) {
340	            if (!ignoreNew || !pet.isNew()) {
341	                String compName = pet.getName();
342	                compName = compName.toLowerCase();
343	                if (compName.equals(name)) {
344	                    return pet;
345	                }
346	            }
347	        }
348	        return null;
349	    }
350	
351	    public Pet getPet(Integer petId) {
352	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
353	    }
354	
355	    @Override
356	    public String toString() {
357	        return new ToStringCreator(this)
358	
359	            .append("id", this.getId())
360	            .append("new", this.isNew())
361	            .append("lastName", this.getLastName())
362	            .append("firstName", this.getFirstName())
363	            .append("title", this.title)
364	            .append("address", this.address)
365	            .append("addressLine1", this.addressLine1)
366	            .append("addressLine2", this.addressLine2)
367	            .append("city", this.city)
368	            .append("telephone", this.telephone)
369	            .append("email", this.email)
370	            .append("postcode", this.postcode)
371	            .append("registrationDate", this.registrationDate)
372	            .append("birthDate", this.birthDate)
373	            .append("memberId", this.memberId)
374	            .append("householdId", this.householdId)
375	            .append("namesakeCount", this.namesakeCount)
376	            .append("householdSize", this.householdSize)
377	            .append("membershipLevelCap", this.membershipLevelCap)
378	            .append("bulkSignupWarning", this.bulkSignupWarning)
379	            .append("capacityWarning", this.capacityWarning)
380	            .append("possibleDuplicate", this.possibleDuplicate)
381	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
382	            .append("deleted", this.deleted)
383	            .toString();
384	    }
385	}
