48	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitException;
49	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainValidator;
50	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
51	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
53	import org.springframework.samples.petclinic.rest.validation.HouseholdIdGenerator;
54	import org.springframework.samples.petclinic.rest.validation.IdentityDuplicateValidator;
55	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
56	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
57	import org.springframework.samples.petclinic.rest.validation.PossibleDuplicateDetector;
58	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
59	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
60	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
61	import org.springframework.samples.petclinic.service.ClinicService;
62	import org.springframework.samples.petclinic.util.BusinessDayResolver;
63	import org.springframework.samples.petclinic.util.IdentityKey;
64	import org.springframework.samples.petclinic.util.LocalityResolver;
65	import org.springframework.samples.petclinic.util.MembershipLevelCalculator;
66	import org.springframework.security.access.prepost.PreAuthorize;
67	import org.springframework.web.bind.annotation.CrossOrigin;
68	import org.springframework.web.bind.annotation.RequestMapping;
69	import org.springframework.web.bind.annotation.RestController;
70	import org.springframework.util.StringUtils;
71	import org.springframework.web.util.UriComponentsBuilder;
