76	/**
77	 * @author Vitaliy Fedoriv
78	 */
79	
80	@RestController
81	@CrossOrigin(exposedHeaders = "errors, content-type")
82	@RequestMapping("/api")
83	public class OwnerRestControllerV1 implements OwnersApi {
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final OwnerFieldsValidator ownerFieldsValidator;
94	
95	    private final PostcodeValidator postcodeValidator;
96	
97	    private final RegistrationDateValidator registrationDateValidator;
98	
99	    private final HouseholdDuplicateValidator householdDuplicateValidator;
100	
101	    private final IdentityDuplicateValidator identityDuplicateValidator;
102	
103	    private final PossibleDuplicateDetector possibleDuplicateDetector;
104	
105	    private final HouseholdIdGenerator householdIdGenerator;
106	
107	    private final TelephoneNormalizer telephoneNormalizer;
108	
109	    private final EmailNormalizer emailNormalizer;
110	
111	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
112	
113	    private final AddressResolver addressResolver;
114	
115	    private final MemberIdGenerator memberIdGenerator;
116	
117	    private final NamesakeCounter namesakeCounter;
118	
119	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
120	
121	    private final CityCapacityWarningEvaluator cityCapacityWarningEvaluator;
122	
123	    private final OwnerAuditLogger ownerAuditLogger;
124	
125	    private final WelcomeNotifier welcomeNotifier;
126	
127	    private final OwnerCreationIdempotencyStore idempotencyStore;
128	
129	    private final HttpServletRequest request;
130	
131	    public OwnerRestControllerV1(ClinicService clinicService,
132	                                 OwnerMapper ownerMapper,
133	                                 PetMapper petMapper,
134	                                 VisitMapper visitMapper,
135	                                 OwnerFieldsValidator ownerFieldsValidator,
136	                                 PostcodeValidator postcodeValidator,
137	                                 RegistrationDateValidator registrationDateValidator,
138	                                 HouseholdDuplicateValidator householdDuplicateValidator,
139	                                 IdentityDuplicateValidator identityDuplicateValidator,
140	                                 PossibleDuplicateDetector possibleDuplicateDetector,
141	                                 HouseholdIdGenerator householdIdGenerator,
142	                                 TelephoneNormalizer telephoneNormalizer,
143	                                 EmailNormalizer emailNormalizer,
144	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
145	                                 AddressResolver addressResolver,
146	                                 MemberIdGenerator memberIdGenerator,
147	                                 NamesakeCounter namesakeCounter,
148	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
149	                                 CityCapacityWarningEvaluator cityCapacityWarningEvaluator,
150	                                 OwnerAuditLogger ownerAuditLogger,
151	                                 WelcomeNotifier welcomeNotifier,
152	                                 OwnerCreationIdempotencyStore idempotencyStore,
153	                                 HttpServletRequest request) {
154	        this.clinicService = clinicService;
155	        this.ownerMapper = ownerMapper;
156	        this.petMapper = petMapper;
157	        this.visitMapper = visitMapper;
158	        this.ownerFieldsValidator = ownerFieldsValidator;
159	        this.postcodeValidator = postcodeValidator;
160	        this.registrationDateValidator = registrationDateValidator;
161	        this.householdDuplicateValidator = householdDuplicateValidator;
162	        this.identityDuplicateValidator = identityDuplicateValidator;
163	        this.possibleDuplicateDetector = possibleDuplicateDetector;
164	        this.householdIdGenerator = householdIdGenerator;
165	        this.telephoneNormalizer = telephoneNormalizer;
166	        this.emailNormalizer = emailNormalizer;
167	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
168	        this.addressResolver = addressResolver;
169	        this.memberIdGenerator = memberIdGenerator;
170	        this.namesakeCounter = namesakeCounter;
171	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
172	        this.cityCapacityWarningEvaluator = cityCapacityWarningEvaluator;
173	        this.ownerAuditLogger = ownerAuditLogger;
174	        this.welcomeNotifier = welcomeNotifier;
175	        this.idempotencyStore = idempotencyStore;
176	        this.request = request;
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
182	        Collection<Owner> owners;
183	        if (lastName != null) {
184	            owners = this.clinicService.findOwnerByLastName(lastName);
185	        } else {
186	            owners = this.clinicService.findAllOwners();
187	        }
188	        if (owners.isEmpty()) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
207	        String idempotencyKey = idempotencyKey();
208	        ResponseEntity<OwnerDto> replay = replayIfDuplicateKey(idempotencyKey);
209	        if (replay != null) {
210	            return replay;
211	        }
212	        addressResolver.resolve(ownerFieldsDto);
213	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
214	        if (!missingFields.isEmpty()) {
215	            throw new MissingOwnerFieldsException(missingFields);
216	        }
217	        HttpHeaders headers = new HttpHeaders();
218	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
219	        Collection<Owner> sameLastName =
220	            activeOwners(this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName()));
221	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
222	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
223	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
224	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
225	        disposableEmailDomainValidator.validate(owner.getEmail());
226	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
227	        rejectIfDuplicateIdentity(owner);
228	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
229	        registrationDateValidator.validate(owner.getRegistrationDate());
230	        if (owner.getRegistrationDate() == null) {
231	            owner.setRegistrationDate(LocalDate.now());
232	        }
233	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
234	        LocalDate registrationDate = owner.getRegistrationDate();
235	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
236	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
237	            throw new DailyOwnerLimitException(registrationDate);
238	        }
239	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
240	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
241	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
242	            throw new CityOwnerLimitException(owner.getCity());
243	        }
244	        owner.setCapacityWarning(cityCapacityWarningEvaluator.isApproachingCapacity(cityOwnerCount));
245	        owner.setMemberId(assignMemberId(owner));
246	        this.clinicService.saveOwner(owner);
247	        if (idempotencyKey != null) {
248	            idempotencyStore.record(idempotencyKey, owner.getId());
249	        }
250	        ownerAuditLogger.ownerCreated(owner);
251	        welcomeNotifier.welcome(owner);
252	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
253	        headers.setLocation(UriComponentsBuilder.newInstance()
254	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
255	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
256	    }
257	
258	    /**
259	     * Reads the request's {@code Idempotency-Key} header, treating a blank value as absent.
260	     *
261	     * @return the trimmed key, or {@code null} when the request carries no usable key
262	     */
263	    private String idempotencyKey() {
264	        String key = request.getHeader("Idempotency-Key");
265	        return StringUtils.hasText(key) ? key.trim() : null;
266	    }
267	
268	    /**
269	     * Replays the owner originally created for an already-seen idempotency key, so a repeated
270	     * create returns that owner with 200 instead of storing a duplicate. Returns {@code null}
271	     * when there is no key or the key has not been seen, in which case the create proceeds
272	     * normally.
273	     */
274	    private ResponseEntity<OwnerDto> replayIfDuplicateKey(String idempotencyKey) {
275	        if (idempotencyKey == null) {
276	            return null;
277	        }
278	        return idempotencyStore.find(idempotencyKey)
279	            .map(clinicService::findOwnerById)
280	            .map(ownerMapper::toOwnerDto)
281	            .map(ownerDto -> new ResponseEntity<>(ownerDto, HttpStatus.OK))
282	            .orElse(null);
283	    }
284	
285	    /**
286	     * Assigns the household attributes of an owner about to be created, without touching any
287	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
288	     * name and postcode, so every owner in the same household shares it automatically regardless of
289	     * creation order. The new owner's household size after this create is recorded: the existing
290	     * members that share its household (same last name and postcode) plus the owner itself.
291	     *
292	     * @return the existing members of the owner's household (empty when it starts a new household)
293	     */
294	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
295	        owner.setHouseholdId(householdIdGenerator.generate(owner));
296	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
297	        owner.setHouseholdSize(members.size() + 1);
298	        return members;
299	    }
300	
301	    /**
302	     * Computes the member id for an owner about to be created, de-duplicated against the ids already
303	     * assigned to existing owners so that distinct owners always receive distinct ids.
304	     *
305	     * @return the owner's unique member id
306	     */
307	    private String assignMemberId(Owner owner) {
308	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
309	        String baseId = memberIdGenerator.generate(
310	            region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
311	        List<String> takenIds = clinicService.findOwnersByMemberIdStartingWith(baseId)
312	            .stream()
313	            .map(Owner::getMemberId)
314	            .toList();
315	        return memberIdGenerator.deduplicate(baseId, takenIds);
316	    }
317	
318	    /**
319	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
320	     * When the owner joins an existing household (same last name and postcode) its membership level
321	     * is capped to at most one above the highest level among the existing members. A member declared
322	     * with {@code sharesHousehold} is, being knowingly registered, not treated as a suspected
323	     * duplicate; an undeclared one still runs the ordinary possible-duplicate detection. When the
324	     * owner starts a new household no cap applies and possible-duplicate detection runs as usual.
325	     */
326	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
327	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
328	        if (householdMembers.isEmpty()) {
329	            flagPossibleDuplicate(owner, sameLastName);
330	            return;
331	        }
332	        owner.setMembershipLevelCap(MembershipLevelCalculator.householdLevelCeiling(householdMembers));
333	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
334	            owner.setPossibleDuplicate(false);
335	            owner.setPossibleDuplicateOf(null);
336	        } else {
337	            flagPossibleDuplicate(owner, sameLastName);
338	        }
339	    }
340	
341	    /**
342	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
343	     * owner. A full-key match requires an equal telephone, so only owners with the same
344	     * (already normalized) telephone are compared.
345	     *
346	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
347	     */
348	    private void rejectIfDuplicateIdentity(Owner owner) {
349	        Collection<Owner> sameTelephone =
350	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
351	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
352	            throw new DuplicateIdentityException(IdentityKey.of(owner));
