356	    /**
357	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
358	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
359	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
360	     */
361	    private List<Owner> activeOwners(Collection<Owner> owners) {
362	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
363	    }
364	
365	    /**
366	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
367	     * existing owner's last name and postcode with a different telephone. The matching owner's id
368	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
369	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
370	     * seen here is guaranteed not to be a hard duplicate.
371	     */
372	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
373	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
374	        owner.setPossibleDuplicate(match != null);
375	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
376	    }
377	
378	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
