384	        }
385	        currentOwner.setAddress(ownerFieldsDto.getAddress());
386	        currentOwner.setCity(ownerFieldsDto.getCity());
387	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
388	        currentOwner.setLastName(ownerFieldsDto.getLastName());
389	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
390	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
391	        this.clinicService.saveOwner(currentOwner);
392	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
393	    }
